const thirdSetValid = (home,away)=>Math.max(home,away)>=12&&Math.abs(home-away)>=2;
assert(thirdSetValid(12,10),"12–10 third-set tiebreak should be valid");
assert(!thirdSetValid(11,10),"11–10 third-set tiebreak should be invalid");

